// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport com.roshan.persona.vision.ocr.OcrBlockimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Real Screen Summarizer (Module 6 v4 — Step 6.6, v1 minimal implementation). * * A [ScreenSummarizer] that produces a template-based summary directly from * the OCR text + UI elements list — without invoking an LLM. This is the v1 * fallback used when [LlmScreenSummarizer] (which calls Module 4's * [com.roshan.persona.brain.llm.provider.LocalLlmProvider]) is unavailable * or fails to load. * * ## Template behavior * * The summary includes: *  - Element count (e.g., "Found 5 UI elements.") *  - First few texts (e.g., "Visible text: Send, Reply, Attach.") *  - OCR text preview (first 100 chars). * * This matches the fallback logic in * [ScreenUnderstandingEngine.fallbackSummary] + [LlmScreenSummarizer.fallbackSummary] * — consistent UX whether the LLM is on or off. * * ## When this is used vs [LlmScreenSummarizer] * * [LlmScreenSummarizer] is the production summarizer (wired via Hilt in * [com.roshan.persona.vision.di.VisionModule]). This class exists as a v1 * fallback + a reference implementation for tests. * * @see LlmScreenSummarizer * @see ScreenSummarizer */@Singletonclass RealScreenSummarizer @Inject constructor() : ScreenSummarizer {    override suspend fun summarize(        ocrText: String,        uiElements: List<UiElement>,        ocrBlocks: List<OcrBlock>,    ): ScreenSummary {        val elementCount = uiElements.size        val texts = uiElements.mapNotNull { it.text }.filter { it.isNotBlank() }        val textPreview = ocrText.take(MAX_PREVIEW_CHARS)        val summary = when {            elementCount > 0 && texts.isNotEmpty() -> {                val preview = texts.take(MAX_VISIBLE_TEXTS).joinToString(", ")                "Found $elementCount UI elements. Visible text: $preview." +                    if (textPreview.isNotBlank()) " Screen text: $textPreview." else ""            }            elementCount > 0 -> {                "Found $elementCount UI elements. No readable text on elements." +                    if (textPreview.isNotBlank()) " Screen text: $textPreview." else ""            }            textPreview.isNotBlank() -> {                "Screen text: $textPreview"            }            else -> {                "I can't read anything on this screen."            }        }        Timber.tag(TAG).d("Generated summary: $summary")        // Lower confidence for template-based summary vs LLM-generated (0.90).        // The ScreenUnderstandingEngine treats confidence < 0.65 as LOW tier.        val confidence = if (elementCount > 0 || textPreview.isNotBlank()) 0.50f else 0.20f        return ScreenSummary(            summary = summary,            spokenSummary = summary,            confidence = confidence,        )    }    private companion object {        private const val TAG = "RealScreenSummarizer"        private const val MAX_VISIBLE_TEXTS = 5        private const val MAX_PREVIEW_CHARS = 100    }}